#!/bin/sh
#
# Generated by the sh backend. Non-POSIX constructs used:
# - 'local': variable scoping (POSIX sh lacks local, but dash/bash/zsh support it)
# - Array emulation (name_0, name_len): arrays are not POSIX
# - '(( ))' arithmetic: required for integer comparison in conditions
# - 'grep -P' helper: PCRE not in POSIX, checked at runtime
#
printf '%b\n' 'line1\nline2\nTARGET\nline4\nline5' | grep -A 2 TARGET
printf '%b\n' 'line1\nline2\nTARGET\nline4\nline5' | grep -B 2 TARGET
printf '%b\n' 'line1\nline2\nTARGET\nline4\nline5' | grep -C 1 TARGET
d="$(mktemp -d)"
cd "$d" || exit 1
printf '%s' 'pattern in file1
' > temp_file1.txt
printf '%s' 'no pattern in file2
' > temp_file2.txt
printf '%s' 'pattern in file3
' > temp_file3.txt
printf '%s\n' 'Recursive search results:'
-r pattern $(find . -name '*.txt')
printf '%s\n' 'Result 2...'
grep -l pattern *.txt | sort
printf '%s\n' 'Result 3...'
grep -L pattern *.txt
cd /
rm -r -f "$d"
matched="$(printf '%s\n' test | grep -c '.*')"
printf '%s\n' "  grep_exit: $?"
printf '%s\n' "  match_count: $matched"
